import {CATEGORIES,localDate,addDays,monday,cents,allocate,initialState,savingsTotals,upsertBudget,validateState} from './core.js';
import {newVault,encryptVault,decryptVault} from './vault.js';
import {workbook} from './excel.js';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal'),STORE='our-little-life.v1';
let state=null,key=null,salt=null,demo=false,tab='overview',week=monday(),habitOwner='All',activePerson='Long',editPeriod=null,baseRaw=null,dirty=false,idle,lastActivity=Date.now(),queue=Promise.resolve(),busy=false;
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const dollars=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(c/100);
const dateLabel=(s,options={month:'short',day:'numeric'})=>new Date(s+'T12:00:00').toLocaleDateString(undefined,options);
const timeLabel=s=>s?new Date(s).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'Not saved yet';
const uid=()=>crypto.randomUUID();
const icons={overview:'▦',budget:'▤',savings:'♡',habits:'✓',reflections:'✎',settings:'⚙'};
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function showDialog(html){modal.innerHTML=`<button class="close" aria-label="Close dialog" data-action="close-modal">×</button>${html}`;modal.showModal();}
function getRaw(){try{return localStorage.getItem(STORE);}catch{throw new Error('Browser storage is unavailable. Enable site storage to save your planner.');}}
function clearSensitive(){state=null;key=null;salt=null;demo=false;dirty=false;editPeriod=null;modal.close();modal.innerHTML='';}
function lock(force=false){if(!force&&dirty&&!confirm('There are unsaved edits. Lock and discard them?'))return;clearSensitive();renderLock();}
async function commit(change,message='Saved on this device'){
 const task=async()=>{if(!state)throw new Error('Unlock your planner first.');busy=true;try{const next=structuredClone(state);change(next);next.updatedAt=new Date().toISOString();validateState(next);if(!demo){const write=async()=>{if(getRaw()!==baseRaw)throw new Error('This planner changed in another tab. Lock and unlock to load the latest version before saving.');const envelope=await encryptVault(next,key,salt);const raw=JSON.stringify(envelope);localStorage.setItem(STORE,raw);baseRaw=raw;};if(navigator.locks)await navigator.locks.request(STORE,write);else await write();}state=next;dirty=false;toast(demo?'Demo updated · not saved to your device':message);return true;}finally{busy=false;}};
 const result=queue.then(task);queue=result.catch(()=>{});try{return await result;}catch(e){toast(e.message);return false;}
}
function plantArt(){return `<svg class="plant-art" viewBox="0 0 280 190" aria-hidden="true"><ellipse cx="140" cy="175" rx="109" ry="9" fill="#dfdad0"/><path d="M200 65l3-12m-9 6h16M48 50l3-12m-9 6h16" stroke="#b7a36f" stroke-width="2"/><path d="M98 133C91 98 97 63 83 37m16 58c27-3 44-32 38-42-29-2-42 26-38 42m-4-22C63 72 45 49 50 39c27-4 43 14 45 34" stroke="#6d8c73" stroke-width="4" fill="#a2b39a"/><path d="M168 133c13-44 7-75 22-102m-11 58c-29-3-38-23-35-34 26-1 34 19 35 34m6-23c24 0 38-18 34-27-24-1-32 13-34 27" stroke="#6d8c73" stroke-width="4" fill="#a2b39a"/><path d="M66 119h65l-9 47q-25 17-48 0z" fill="#cf8e9a"/><path d="M145 119h66l-8 47q-25 17-49 0z" fill="#e4bd9f"/><rect x="62" y="113" width="73" height="13" rx="5" fill="#dca1aa"/><rect x="141" y="113" width="74" height="13" rx="5" fill="#ebc7ac"/><path d="M85 143q4 5 8 0m13 0q4 5 8 0m51 0q4 5 8 0m13 0q4 5 8 0m-101 9q5 5 10 0m65 0q5 5 10 0" fill="none" stroke="#614c46" stroke-width="2" stroke-linecap="round"/><path d="M140 44c-14-14-28 4 0 19 28-15 14-33 0-19" fill="#c88794"/><circle cx="40" cy="100" r="3" fill="#c9b283"/><circle cx="235" cy="108" r="3" fill="#c9b283"/></svg>`;}
function renderLock(){clearInterval(idle);let exists=false;try{exists=!!getRaw();}catch(e){toast(e.message);}app.innerHTML=`<main class="welcome"><a class="brand" href="#"><span class="brand-icon">♡</span><span>our little life<small>LONG & MEI</small></span></a><div class="welcome-grid"><section><span class="eyebrow">A LITTLE INTENTION. A LOT OF LOVE.</span><h1>Good things<br>grow <em>together.</em></h1><p>A cozy corner for your money, your habits,<br>and the life you're building side by side.</p>${plantArt()}<div class="welcome-tags"><span>♡ Shared dreams</span><span>✓ Little routines</span><span>✎ Honest reflections</span></div></section><section class="card welcome-card"><span class="pill">♡ JUST FOR LONG & MEI</span><h2>${exists?'Welcome home, you two.':'Your little life starts here.'}</h2><p>${exists?'Unlock your private planner to pick up where you left off.':'Create a private planner with a passphrase only you two know.'}</p><form id="vault-form"><label>Shared passphrase<input name="password" type="password" autocomplete="${exists?'current-password':'new-password'}" minlength="12" required placeholder="At least 12 characters"></label>${exists?'':`<label>Confirm passphrase<input name="confirm" type="password" autocomplete="new-password" minlength="12" required placeholder="One more time"></label>`}<p class="form-error" id="vault-error" role="alert"></p><button class="primary full" type="submit">${exists?'Unlock our planner':'Create our planner'} <span>→</span></button></form><button class="text-button full" data-action="demo">Take a peek at the demo ↗</button><div class="security-note">♧ <div><strong>Private by design</strong><p>Saved data is encrypted on this browser. No account or cloud sync. Keep an encrypted backup; clearing browser data removes your copy. A forgotten passphrase cannot be recovered.</p></div></div><button class="text-button" data-action="restore">Restore an encrypted backup</button></section></div><footer>Made for the everyday, and everything ahead. <span>Long + Mei ♡</span></footer></main>`;
 $('#vault-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),password=f.get('password'),btn=e.target.querySelector('button');btn.disabled=true;$('#vault-error').textContent='';try{if(!crypto.subtle)throw new Error('Open this planner over HTTPS or localhost to use encryption.');const raw=getRaw();if(raw){const result=await decryptVault(JSON.parse(raw),password);state=validateState(result.data);key=result.key;salt=result.salt;baseRaw=raw;}else{if(password!==f.get('confirm'))throw new Error('The passphrases do not match.');const v=await newVault(password);const data=initialState();const saved=JSON.stringify(await encryptVault(data,v.key,v.salt));if(getRaw())throw new Error('A planner was just created in another tab. Reload this page.');localStorage.setItem(STORE,saved);state=data;key=v.key;salt=v.salt;baseRaw=saved;}demo=false;tab='overview';dirty=false;render();startIdle();}catch(err){$('#vault-error').textContent=err.message;btn.disabled=false;}});
}
function startIdle(){clearInterval(idle);lastActivity=Date.now();idle=setInterval(()=>{if(state&&!demo&&!busy&&Date.now()-lastActivity>5*60000){lock(true);toast('Locked after 5 minutes of inactivity. Unsaved edits were discarded.');}},15000);}
function demoState(){const s=initialState();s.goals.Long.opening=35000;s.goals.Mei.opening=52000;s.goals.Together.opening=180000;const start=addDays(monday(),-14);s.budgets=[{start,savedAt:new Date().toISOString(),people:{Long:{income:600,percentages:{needs:50,personal:15,joint:10,debt:15,fun:10}},Mei:{income:900,percentages:{needs:45,personal:20,joint:15,debt:10,fun:10}}}}];for(let i=0;i<4;i++)for(let j=0;j<3;j++)if(addDays(monday(),j)<=localDate())s.checks[`${s.habits[i].id}:${addDays(monday(),j)}`]=true;s.reflections=[{id:'demo-note',date:localDate(),owner:'Together',mood:'Grateful',text:'Proud of us for making time for a little money date. Small steps still count. ♡',savedAt:new Date().toISOString()}];return s;}
function render(){if(!state)return renderLock();const totals=savingsTotals(state),titles={overview:['Our little overview','A little progress, a little closer.'],budget:['Let’s make a little plan','Give every dollar a place to grow.'],savings:['Dreams we’re growing','Your own goals, and the ones you share.'],habits:['Little things, every day','Progress over perfection. Always.'],reflections:['A moment for us','Look back with kindness. Look ahead together.'],settings:['Keep your little life safe','Your planner, your data, your control.']};
 app.innerHTML=`<div class="layout"><aside><a href="#" class="brand" data-nav="overview"><span class="brand-icon">♡</span><span>our little life<small>LONG & MEI</small></span></a><div class="couple"><span class="avatar long">L</span><span class="heart">♡</span><span class="avatar mei">M</span><strong>Better, together.</strong><small>Our shared space</small></div><nav aria-label="Main navigation">${Object.keys(titles).map(t=>`<button data-nav="${t}" class="nav-item ${tab===t?'active':''}" ${tab===t?'aria-current="page"':''}><span>${icons[t]}</span>${{overview:'Overview',budget:'Our budget',savings:'Savings & dreams',habits:'Little habits',reflections:'Reflections',settings:'Privacy & backup'}[t]}</button>`).join('')}</nav><div class="sidebar-note"><span>✿</span><p>Little by little,<br>a life we love.</p></div><button class="lock" data-action="lock">♧ ${demo?'Leave demo':'Lock our planner'}</button></aside><main class="main"><header><div><span class="eyebrow">OUR COUPLE PLANNER</span><h1>${titles[tab][0]}</h1><p>${titles[tab][1]}</p></div><div class="header-right"><div class="today"><span>✧</span><div><small>TODAY</small><strong id="current-date">${new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</strong></div></div><button class="secondary" data-action="export">↓ Export Excel</button></div></header>${demo?'<div class="banner">You’re exploring a demo with sample numbers. Nothing here is saved. <button data-action="lock">Set up our real planner →</button></div>':''}<div class="save-strip"><span class="status-dot"></span><span>${demo?'Demo mode':`Encrypted · saved on this device${state.updatedAt?' · '+timeLabel(state.updatedAt):''}`}</span><span class="right-label">Long + Mei <span class="pink">♡</span></span></div><div id="content">${tab==='overview'?overview(totals):tab==='budget'?budgetView():tab==='savings'?savingsView(totals):tab==='habits'?habitsView():tab==='reflections'?reflectionsView():settingsView()}</div><footer>Every small step is a step together. <span>Made with a little love ♡</span></footer></main></div>`;
 if(tab==='budget')bindBudget();if(tab==='reflections')bindReflection();if(tab==='savings')bindGoals();
}
function overview(totals){const latest=state.budgets[0],a=latest?combined(latest):null;const today=localDate(),active=state.habits.filter(h=>!h.archived),checked=active.filter(h=>state.checks[h.id+':'+today]).length;return `<section class="hero"><div><span class="eyebrow">THE LIFE WE’RE BUILDING</span><h2>Small steps.<br><em>Shared dreams.</em></h2><p>A budget that feels good. Habits that stick.<br>And a little space to grow, together.</p><button class="primary" data-nav="budget">Plan our next two weeks <span>→</span></button></div>${plantArt()}<span class="hero-stamp">growing<br>with you ♡</span></section><div class="section-heading"><h2>A little check-in</h2><span>Every bit counts ✧</span></div><div class="stats"><article class="card stat"><span class="stat-icon sage">↗</span><small>OUR JOINT SAVINGS</small><h3>${dollars(totals.Together)}</h3><p>For all the things ahead <span>♡</span></p></article><article class="card stat"><span class="stat-icon lilac">♧</span><small>PERSONAL SAVINGS</small><h3>${dollars(totals.Long+totals.Mei)}</h3><p>Long ${dollars(totals.Long)} · Mei ${dollars(totals.Mei)}</p></article><article class="card stat"><span class="stat-icon peach">✓</span><small>TODAY’S LITTLE WINS</small><h3>${checked} <span class="muted">/ ${active.length}</span></h3><p>${checked===active.length&&active.length?'Look at you two go!':'One small habit at a time'}</p></article></div><div class="two-column"><section class="card"><div class="section-heading"><h2>Our money, with intention</h2><button class="text-button" data-nav="budget">View budget ↗</button></div><p class="subtitle">${latest?dateLabel(latest.start)+' – '+dateLabel(addDays(latest.start,13))+ ' · latest saved period':'Your next two weeks start with a plan'}</p>${latest?`<div class="budget-overview"><div class="donut" style="${donutStyle(a)}"><div><small>BIWEEKLY INCOME</small><strong>${dollars(a.income)}</strong><span>together</span></div></div><div class="legend">${CATEGORIES.map(c=>`<div><span class="dot" style="background:${c.color}"></span><span>${c.short}</span><strong>${dollars(a[c.key])}</strong></div>`).join('')}</div></div>`:`<div class="empty"><span>◌</span><h3>A fresh little start</h3><p>Add both incomes and choose your percentages.<br>We’ll do the math for you.</p><button class="secondary" data-nav="budget">Create our first budget →</button></div>`}</section><section class="card"><div class="section-heading"><h2>Today’s little habits</h2><button class="text-button" data-nav="habits">View all ↗</button></div><p class="subtitle">Show up for yourself. Show up for each other.</p><div class="today-habits">${active.slice(0,5).map(h=>`<button class="today-habit ${state.checks[h.id+':'+today]?'done':''}" data-check="${esc(h.id)}" data-date="${today}" aria-pressed="${!!state.checks[h.id+':'+today]}"><span class="check-circle">${state.checks[h.id+':'+today]?'✓':''}</span><span>${esc(h.name)}<small>${h.owner}</small></span><span class="mini-avatar ${h.owner==='Mei'?'mei':'long'}">${h.owner==='Together'?'♡':h.owner[0]}</span></button>`).join('')||'<p>Add your first habit to start a gentle routine.</p>'}</div></section></div><section class="reflection-teaser"><span>✎</span><div><h2>How are we doing, really?</h2><p>${state.reflections[0]?esc(state.reflections[0].text.slice(0,140)):'A good thing from today, a small win, or something on your mind.'}</p></div><button class="secondary" data-nav="reflections">A moment to reflect →</button></section><p class="footnote">Savings shown are planned amounts from saved budgets plus your opening balances; they are not connected bank balances.</p>`;}
function combined(b){const out={income:0};for(const c of CATEGORIES)out[c.key]=0;for(const p of ['Long','Mei']){out.income+=cents(b.people[p].income);const a=allocate(b.people[p].income,b.people[p].percentages);for(const c of CATEGORIES)out[c.key]+=a[c.key];}return out;}
function donutStyle(a){let start=0;return 'background:conic-gradient('+CATEGORIES.map(c=>{const end=start+(a.income?a[c.key]/a.income*100:20);const x=`${c.color} ${start}% ${end}%`;start=end;return x;}).join(',')+')';}
function budgetView(){const b=editPeriod?state.budgets.find(b=>b.start===editPeriod):null;let start=b?.start||localDate();if(!b&&state.budgets.length)start=addDays(state.budgets[0].start,14);return `<form id="budget-form"><section class="card"><div class="section-heading"><div><span class="eyebrow">YOUR BIWEEKLY MONEY DATE</span><h2>${b?'Edit a saved plan':'A plan for the next two weeks'}</h2></div><label class="date-input">Period begins<input type="date" name="start" value="${start}" required ${b?'readonly':''}></label></div><p class="subtitle">Enter take-home income for each full 14-day period. Each person’s allocation should total 100%.</p><div class="people-inputs">${['Long','Mei'].map(p=>`<div class="income-card ${p.toLowerCase()}"><div><span class="avatar ${p.toLowerCase()}">${p[0]}</span><h3>${p}’s income</h3><span class="pill">EVERY 2 WEEKS</span></div><label>Take-home pay ($)<input name="${p}-income" type="number" min="0" max="1000000000" step="0.01" value="${b?.people[p].income??''}" placeholder="0.00" required></label></div>`).join('')}</div><div class="allocation-heading"><h3>Give your income a little direction</h3><div class="segmented">${['Long','Mei'].map(p=>`<button type="button" data-person="${p}" class="${activePerson===p?'selected':''}">${p}</button>`).join('')}</div></div>${['Long','Mei'].map(p=>`<div class="allocation-panel" data-panel="${p}" ${activePerson!==p?'hidden':''}>${CATEGORIES.map(c=>`<div class="allocation-row"><span class="dot" style="background:${c.color}"></span><label for="${p}-${c.key}">${c.name}</label><div class="percent-input"><input id="${p}-${c.key}" name="${p}-${c.key}" type="number" min="0" max="100" step="0.1" required value="${b?.people[p].percentages[c.key]??c.pct}"><span>%</span></div><output id="${p}-${c.key}-amount">$0.00</output></div>`).join('')}<div class="allocation-total"><strong>Allocated</strong><span id="${p}-total">100%</span></div></div>`).join('')}<div id="budget-error" class="form-error" role="alert"></div></section><section class="card calculator-result"><div><span class="eyebrow">YOUR SAVINGS, AT A GLANCE</span><h2>Watch your little plan add up.</h2><p class="subtitle">Weekly amounts are the biweekly plan ÷ 2.</p></div><div id="calculation"></div></section><div class="form-actions"><p>Saving updates this period’s plan. It does not move money.</p>${b?'<button type="button" class="secondary" data-action="new-budget">New period</button>':''}<button class="primary" type="submit">${b?'Save changes':'Save our budget'} <span>♡</span></button></div></form><div class="section-heading"><h2>Our saved plans</h2><span>${state.budgets.length} periods</span></div><section class="card table-wrap"><table><thead><tr><th>Two-week period</th><th>Income</th><th>Personal savings</th><th>Joint savings</th><th>Saved</th><th></th></tr></thead><tbody>${state.budgets.map(b=>{const a=combined(b);return `<tr><td>${dateLabel(b.start,{month:'short',day:'numeric',year:'numeric'})} – ${dateLabel(addDays(b.start,13))}</td><td>${dollars(a.income)}</td><td>${dollars(a.personal)}</td><td>${dollars(a.joint)}</td><td>${timeLabel(b.savedAt)}</td><td><button class="text-button" data-edit-budget="${b.start}">Edit</button></td></tr>`;}).join('')||'<tr><td colspan="6" class="empty-cell">Your saved plans will live here.</td></tr>'}</tbody></table></section>`;}
function readBudget(form){const f=new FormData(form),b={start:f.get('start'),savedAt:new Date().toISOString(),people:{}};for(const p of ['Long','Mei'])b.people[p]={income:Number(f.get(p+'-income')),percentages:Object.fromEntries(CATEGORIES.map(c=>[c.key,Number(f.get(p+'-'+c.key))]))};return b;}
function bindBudget(){const form=$('#budget-form');function calculate(){const b=readBudget(form);let valid=true;for(const p of ['Long','Mei']){const x=b.people[p],total=Object.values(x.percentages).reduce((s,n)=>s+n,0);$('#'+p+'-total').textContent=Number(total.toFixed(2))+'%';$('#'+p+'-total').className=Math.abs(total-100)>.001?'error':'good';let a;try{a=allocate(x.income,x.percentages);}catch{valid=false;}for(const c of CATEGORIES)$('#'+p+'-'+c.key+'-amount').textContent=a?dollars(a[c.key]):'—';}$('#budget-error').textContent=valid?'':'Each person’s percentages must total 100%, and income cannot be negative.';if(valid){const a=combined(b);$('#calculation').innerHTML=`<div class="calculation-stats"><div><small>Combined income / 2 weeks</small><strong>${dollars(a.income)}</strong></div><div><small>Personal savings / 2 weeks</small><strong>${dollars(a.personal)}</strong></div><div><small>Joint savings / 2 weeks</small><strong>${dollars(a.joint)}</strong></div><div class="highlight"><small>All savings / week</small><strong>${dollars(Math.round((a.personal+a.joint)/2))}</strong></div></div><div class="weekly-detail">${['Long','Mei'].map(p=>{const t=allocate(b.people[p].income,b.people[p].percentages);return `<span><b>${p}</b> · ${dollars(Math.round((t.personal+t.joint)/2))} saved / week</span>`;}).join('')}<span>Joint pot · ${dollars(Math.round(a.joint/2))} / week</span></div>`;}else $('#calculation').innerHTML='<p>Adjust your percentages to see your savings.</p>';}
 form.addEventListener('input',()=>{dirty=true;calculate();});form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const b=readBudget(form);try{combined(b);if(await commit(s=>upsertBudget(s,b),'Our budget is saved ♡')){editPeriod=b.start;render();}}catch(e){toast(e.message);}});calculate();}
function savingsView(totals){return `<section class="savings-intro"><span class="eyebrow">A LITTLE NOW. A LOVELY LATER.</span><h2>Room for your dreams.<br><em>And room for ours.</em></h2><p>Set an opening balance and a goal. Saved budget allocations grow these planned totals.</p></section><form id="goals-form"><div class="goals-grid">${['Long','Mei','Together'].map(p=>{const g=state.goals[p],pct=g.target?Math.min(100,Math.round(totals[p]/g.target*100)):0;return `<section class="card goal ${p.toLowerCase()}"><div class="goal-top"><span class="avatar ${p==='Together'?'joint':p.toLowerCase()}">${p==='Together'?'♡':p[0]}</span><span class="pill">${p==='Together'?'OUR SHARED DREAM':'JUST FOR '+p.toUpperCase()}</span></div><h2>${p==='Together'?'Our joint savings':p+'’s personal savings'}</h2><strong class="goal-amount">${dollars(totals[p])}</strong><p>planned balance</p><div class="progress" role="progressbar" aria-label="${p} goal progress" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><span style="width:${pct}%"></span></div><div class="goal-progress"><span>${pct}% of our goal</span><span>${dollars(g.target)}</span></div><label>Opening balance ($)<input type="number" step="0.01" min="0" max="1000000000" name="${p}-opening" value="${g.opening/100}" required></label><label>Savings goal ($)<input type="number" step="0.01" min="0" max="1000000000" name="${p}-target" value="${g.target/100}" required></label><small>Opening balance + ${dollars(totals[p]-g.opening)} from saved plans.</small></section>`;}).join('')}</div><div class="form-actions"><p>Opening balances should exclude the contributions in your saved plans.</p><button class="primary">Save our goals ♡</button></div></form><section class="note-card"><span>✧</span><div><h3>Your money can have more than one purpose.</h3><p>Personal savings stay separate for Long and Mei. The joint pot combines both of your joint contributions. These are planning totals, so check your bank before spending.</p></div></section>`;}
function bindGoals(){const f=$('#goals-form');f.addEventListener('input',()=>dirty=true);f.addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(f);try{const goals=Object.fromEntries(['Long','Mei','Together'].map(p=>[p,{opening:cents(data.get(p+'-opening')),target:cents(data.get(p+'-target'))}]));if(await commit(s=>s.goals=goals,'Your goals are saved ♡'))render();}catch(e){toast(e.message);}});}
function habitsView(){const days=Array.from({length:7},(_,i)=>addDays(week,i)),today=localDate(),habits=state.habits.filter(h=>!h.archived&&(habitOwner==='All'||h.owner===habitOwner));const elapsed=days.filter(d=>d<=today).length,total=habits.length*elapsed,done=habits.reduce((s,h)=>s+days.filter(d=>d<=today&&state.checks[h.id+':'+d]).length,0);return `<section class="card"><div class="section-heading"><div><span class="eyebrow">SHOWING UP TOGETHER</span><h2>Our little habit garden</h2></div><button class="primary" data-action="add-habit">+ Add a habit</button></div><div class="habit-toolbar"><div class="segmented">${['All','Long','Mei','Together'].map(p=>`<button data-owner="${p}" class="${habitOwner===p?'selected':''}">${p}</button>`).join('')}</div><div class="week-nav"><button class="icon-button" aria-label="Previous week" data-week="-7">‹</button><strong>${dateLabel(week)} – ${dateLabel(days[6])}</strong><button class="icon-button" aria-label="Next week" data-week="7">›</button><button class="text-button" data-action="this-week">Today</button></div></div><div class="table-wrap"><table class="habit-table"><thead><tr><th>Little habit</th>${days.map(d=>`<th class="${d===today?'is-today':''}">${dateLabel(d,{weekday:'short'})}<span>${dateLabel(d,{day:'numeric'})}</span></th>`).join('')}<th></th></tr></thead><tbody>${habits.map(h=>`<tr><td><strong>${esc(h.name)}</strong><small>${h.owner}</small></td>${days.map(d=>`<td><button class="habit-check ${state.checks[h.id+':'+d]?'checked':''}" data-check="${esc(h.id)}" data-date="${d}" aria-label="${esc(h.owner+' '+h.name+' on '+d)}" aria-pressed="${!!state.checks[h.id+':'+d]}" ${d>today?'disabled':''}>${state.checks[h.id+':'+d]?'✓':'·'}</button></td>`).join('')}<td><button class="text-button" data-archive-habit="${esc(h.id)}" aria-label="Archive ${esc(h.name)} for ${h.owner}">×</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty-cell">Plant a new habit with the button above.</td></tr>'}</tbody></table></div><div class="habit-footer"><span>✓ <b>${done}</b> little wins this week</span><span>${total?Math.round(done/total*100):0}% of check-ins through today</span><small>Tap a circle to save a check-in.</small></div></section><section class="note-card"><span>✿</span><div><h3>You don’t have to do it perfectly.</h3><p>Some weeks bloom, some weeks you just water the seeds. Both count.</p></div></section>${state.habits.some(h=>h.archived)?`<details class="card"><summary>Archived habits</summary>${state.habits.filter(h=>h.archived).map(h=>`<div class="archive-row">${esc(h.name)} · ${h.owner}<button class="text-button" data-unarchive="${esc(h.id)}">Restore</button></div>`).join('')}</details>`:''}`;}
function reflectionsView(){return `<div class="reflection-layout"><section class="card"><span class="eyebrow">PAUSE. BREATHE. CHECK IN.</span><h2>What’s on your mind?</h2><p class="subtitle">A small win, a challenge, or something you’re grateful for.</p><form id="reflection-form"><input type="hidden" name="id" value=""><div class="form-row"><label>From<select name="owner"><option>Together</option><option>Long</option><option>Mei</option></select></label><label>Reflection date<input type="date" name="date" value="${localDate()}" required></label></div><label>How does today feel?<select name="mood"><option>Grateful</option><option>Happy</option><option>Hopeful</option><option>Okay</option><option>Tired</option><option>Overwhelmed</option></select></label><label>Our little reflection<textarea name="text" rows="8" maxlength="10000" placeholder="Today, I’m grateful for…" required></textarea></label><div class="form-actions"><small id="reflection-status">A space to be honest, and kind.</small><button class="primary" type="submit">Save reflection ♡</button></div></form></section><section><div class="section-heading"><h2>Pages from our life</h2><span>${state.reflections.length} reflections</span></div><div class="notes-list">${state.reflections.map(r=>`<article class="card reflection-note"><div><span class="pill">${esc(r.mood)}</span><span class="note-date">${dateLabel(r.date,{month:'short',day:'numeric',year:'numeric'})}</span></div><p>${esc(r.text)}</p><div class="note-meta"><span>${r.owner} <span class="pink">♡</span><small>Saved ${timeLabel(r.savedAt)}</small></span><button class="text-button" data-edit-reflection="${esc(r.id)}">Edit ✎</button></div></article>`).join('')||'<div class="empty card"><span>✎</span><h3>The first page is yours.</h3><p>Your saved reflections will appear here,<br>with the date you wrote them.</p></div>'}</div></section></div>`;}
function bindReflection(){const f=$('#reflection-form');f.addEventListener('input',()=>dirty=true);f.addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(f);if(!data.get('text').trim()){toast('Write a little something first.');return;}const r={id:data.get('id')||uid(),date:data.get('date'),owner:data.get('owner'),mood:data.get('mood'),text:data.get('text').trim(),savedAt:new Date().toISOString()};if(await commit(s=>{const i=s.reflections.findIndex(x=>x.id===r.id);if(i<0)s.reflections.unshift(r);else s.reflections[i]=r;s.reflections.sort((a,b)=>b.savedAt.localeCompare(a.savedAt));},'Your reflection is saved ♡'))render();});}
function settingsView(){return `<div class="two-column"><section class="card"><span class="eyebrow">YOUR PRIVATE LITTLE SPACE</span><h2>Saved here. Encrypted here.</h2><p>Your saved budgets, habits and notes are encrypted with your shared passphrase on this browser. They are never uploaded to GitHub.</p><ul class="privacy-list"><li><strong>AES-256-GCM encryption</strong><span>A fresh random IV for every save; a passphrase-derived key using PBKDF2-SHA256 with 600,000 iterations.</span></li><li><strong>Locks after 5 minutes idle</strong><span>Save your edits before stepping away. Unsaved edits are discarded when the planner locks.</span></li><li><strong>No password recovery</strong><span>Keep your passphrase somewhere safe. We can’t reset it or decrypt your data without it.</span></li></ul><p class="footnote">No website is hack-proof. Use a long, unique passphrase and a trusted device. Malicious browser extensions, a compromised device or altered website code can expose information while unlocked. Protect the GitHub account with two-factor authentication.</p><button class="secondary" data-action="change-password">Change shared passphrase</button></section><section class="card"><span class="eyebrow">TAKE YOUR LITTLE LIFE WITH YOU</span><h2>Back up, share, restore.</h2><p>This version does not automatically sync between devices. Download an encrypted backup and restore it on Mei’s device using the same passphrase.</p><div class="backup-actions"><button class="primary" data-action="backup">↓ Download encrypted backup</button><button class="secondary" data-action="restore">↑ Restore encrypted backup</button><button class="secondary" data-action="export">↓ Export Excel workbook</button></div><div class="warning-note">Restoring replaces this browser’s planner; it does not merge two copies. Keep one primary copy and back up before switching devices.</div><p class="footnote">Excel exports are not password-protected. Store them privately. Encrypted backups are the safer option for sharing. Clearing browser data removes the saved planner from this device.</p></section></div>`;}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function exportExcel(){showDialog(`<span class="eyebrow">YOUR PLANNER, IN A WORKBOOK</span><h2>Export our little life</h2><p>Your Excel file includes saved budgets, savings goals, habit check-ins, and reflections. Unsaved edits are not included.</p><div class="warning-note">This Excel file is readable without your passphrase. Keep it private.</div><button class="primary full" data-action="confirm-export">Download .xlsx</button>`);}
function makeWorkbook(){const sums=savingsTotals(state);const budgetRows=[['Period start','Period end','Person','Income (USD)',...CATEGORIES.map(c=>c.name+' (USD)'),...CATEGORIES.map(c=>c.short+' (%)'),'Saved at']];for(const b of state.budgets)for(const p of ['Long','Mei']){const a=allocate(b.people[p].income,b.people[p].percentages);budgetRows.push([b.start,addDays(b.start,13),p,b.people[p].income,...CATEGORIES.map(c=>a[c.key]/100),...CATEGORIES.map(c=>b.people[p].percentages[c.key]),b.savedAt]);}return workbook([{name:'Read me',rows:[['Our Little Life','Long & Mei'],['Exported at',new Date().toISOString()],['Currency','USD'],['Savings','Planned contributions, not verified bank balances'],['Privacy','This workbook is not encrypted. Keep it private.'],['Habit data','Only checked dates are listed. Missing dates are not complete.']]},{name:'Biweekly budgets',rows:budgetRows},{name:'Savings goals',rows:[['Owner','Opening balance (USD)','Planned contributions (USD)','Planned balance (USD)','Goal (USD)'],...['Long','Mei','Together'].map(p=>[p,state.goals[p].opening/100,(sums[p]-state.goals[p].opening)/100,sums[p]/100,state.goals[p].target/100])]},{name:'Habits',rows:[['Habit ID','Habit','Owner','Archived'],...state.habits.map(h=>[h.id,h.name,h.owner,h.archived?'Yes':'No'])]},{name:'Check-ins',rows:[['Date','Habit','Owner','Completed'],...Object.entries(state.checks).filter(([,v])=>v).map(([k])=>{const at=k.lastIndexOf(':'),h=state.habits.find(h=>h.id===k.slice(0,at));return [k.slice(at+1),h?.name||'Unknown habit',h?.owner||'', 'Yes'];}).sort((a,b)=>a[0].localeCompare(b[0]))]},{name:'Reflections',rows:[['Date','From','Mood','Reflection','Saved at'],...state.reflections.map(r=>[r.date,r.owner,r.mood,r.text,r.savedAt])]}]);}
async function backup(){if(demo){toast('Demo data has no encrypted backup. Create your real planner first.');return;}if(dirty){toast('Save your edits before downloading a backup.');return;}if(busy)await queue;const raw=getRaw();if(raw!==baseRaw){toast('Another tab changed this planner. Lock and unlock before backing up.');return;}download(new Blob([raw],{type:'application/json'}),`long-mei-${localDate()}.encrypted.json`);toast('Encrypted backup downloaded. Keep it with your passphrase stored separately.');}
function restoreDialog(){showDialog(`<span class="eyebrow">BRING YOUR PLANNER HOME</span><h2>Restore an encrypted backup</h2><p>Choose your backup file and enter the passphrase used when it was created.</p><form id="restore-form"><label>Backup file<input name="file" type="file" accept=".json,application/json" required></label><label>Backup passphrase<input name="password" type="password" autocomplete="off" required></label><label class="checkbox-label"><input name="confirm" type="checkbox" required> I understand this replaces this browser’s planner. I have backed up any data I want to keep.</label><p id="restore-error" class="form-error" role="alert"></p><button class="primary full">Decrypt and restore</button></form>`);$('#restore-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,button=f.querySelector('button');button.disabled=true;try{if(busy)await queue;const expected=getRaw(),data=new FormData(f),file=data.get('file');if(file.size>15e6)throw new Error('Backup file is too large.');const raw=await file.text(),v=await decryptVault(JSON.parse(raw),data.get('password'));validateState(v.data);const write=()=>{if(getRaw()!==expected)throw new Error('Planner changed in another tab. Try again after reviewing the latest data.');localStorage.setItem(STORE,raw);};if(navigator.locks)await navigator.locks.request(STORE,write);else write();state=v.data;key=v.key;salt=v.salt;baseRaw=raw;demo=false;dirty=false;editPeriod=null;tab='overview';modal.close();modal.innerHTML='';render();startIdle();toast('Your planner is restored ♡');}catch(e){$('#restore-error').textContent=e.message;button.disabled=false;}});}
function changePassword(){if(demo){toast('Create a real planner to set a passphrase.');return;}showDialog(`<h2>A new shared passphrase</h2><p>Old backup files still need the old passphrase. Download a new backup after changing it.</p><form id="password-form"><label>Current passphrase<input name="old" type="password" autocomplete="current-password" required></label><label>New passphrase<input name="new" type="password" minlength="12" autocomplete="new-password" required></label><label>Confirm new passphrase<input name="confirm" type="password" minlength="12" autocomplete="new-password" required></label><p class="form-error" id="password-error" role="alert"></p><button class="primary full">Save new passphrase</button></form>`);$('#password-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,data=new FormData(f),button=f.querySelector('button');button.disabled=true;busy=true;try{await queue;if(data.get('new')!==data.get('confirm'))throw new Error('New passphrases do not match.');await decryptVault(JSON.parse(baseRaw),data.get('old'));const next=await newVault(data.get('new'));const raw=JSON.stringify(await encryptVault(state,next.key,next.salt));const write=()=>{if(getRaw()!==baseRaw)throw new Error('Planner changed in another tab. Lock and unlock first.');localStorage.setItem(STORE,raw);};if(navigator.locks)await navigator.locks.request(STORE,write);else write();key=next.key;salt=next.salt;baseRaw=raw;modal.close();modal.innerHTML='';toast('Passphrase changed. Download a fresh encrypted backup.');}catch(e){$('#password-error').textContent=e.message;button.disabled=false;}finally{busy=false;}});}
function canNavigate(){return !dirty||confirm('You have unsaved edits. Leave this page and discard them?');}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;lastActivity=Date.now();if(busy){e.preventDefault();toast('Finishing your save…');return;}try{
 if(b.dataset.nav){e.preventDefault();if(!canNavigate())return;tab=b.dataset.nav;dirty=false;render();window.scrollTo({top:0,behavior:'smooth'});return;}
 if(b.dataset.person){activePerson=b.dataset.person;document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==activePerson);document.querySelectorAll('[data-person]').forEach(p=>p.classList.toggle('selected',p.dataset.person===activePerson));return;}
 if(b.dataset.check){const k=b.dataset.check+':'+b.dataset.date;if(await commit(s=>s.checks[k]=!s.checks[k],'A little win, saved ♡'))render();return;}
 if(b.dataset.owner){habitOwner=b.dataset.owner;render();return;}
 if(b.dataset.week){week=addDays(week,Number(b.dataset.week));render();return;}
 if(b.dataset.editBudget){if(!canNavigate())return;editPeriod=b.dataset.editBudget;dirty=false;render();window.scrollTo({top:0,behavior:'smooth'});return;}
 if(b.dataset.editReflection){if(!canNavigate())return;const r=state.reflections.find(r=>r.id===b.dataset.editReflection),f=$('#reflection-form');for(const k of ['id','date','owner','mood','text'])f.elements[k].value=r[k];$('#reflection-status').textContent='Editing · last saved '+timeLabel(r.savedAt);dirty=false;f.elements.text.focus();f.scrollIntoView({behavior:'smooth',block:'center'});return;}
 if(b.dataset.archiveHabit||b.dataset.unarchive){const id=b.dataset.archiveHabit||b.dataset.unarchive;if(await commit(s=>{s.habits.find(h=>h.id===id).archived=!!b.dataset.archiveHabit;},b.dataset.archiveHabit?'Habit archived; history kept.':'Habit restored.'))render();return;}
 switch(b.dataset.action){case 'close-modal':modal.close();modal.innerHTML='';break;case 'demo':state=demoState();demo=true;tab='overview';render();window.scrollTo(0,0);startIdle();break;case 'lock':lock();break;case 'new-budget':if(canNavigate()){editPeriod=null;dirty=false;render();}break;case 'this-week':week=monday();render();break;case 'export':exportExcel();break;case 'confirm-export':download(makeWorkbook(),`long-mei-planner-${localDate()}.xlsx`);modal.close();toast('Your Excel workbook is downloaded.');break;case 'backup':await backup();break;case 'restore':restoreDialog();break;case 'change-password':changePassword();break;case 'add-habit':showDialog(`<span class="eyebrow">PLANT A LITTLE ROUTINE</span><h2>A new habit to grow</h2><form id="habit-form"><label>Habit name<input name="name" maxlength="100" placeholder="e.g. Take a walk together" required></label><label>Who is it for?<select name="owner"><option>Together</option><option>Long</option><option>Mei</option></select></label><button class="primary full">Add our little habit</button></form>`);$('#habit-form').addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(e.target),name=data.get('name').trim();if(!name)return;const owner=data.get('owner');if(await commit(s=>s.habits.push({id:uid(),name,owner,archived:false}),'A new habit is planted ♡')){modal.close();render();}});break;}
 }catch(error){toast(error.message);}});
['pointerdown','keydown','input','scroll'].forEach(name=>document.addEventListener(name,()=>lastActivity=Date.now(),{passive:true}));
window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}});
window.addEventListener('storage',e=>{if(e.key===STORE&&state&&!demo)toast('Saved data changed in another tab. Lock and unlock before editing.');});
setInterval(()=>{const d=$('#current-date');if(d)d.textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'});},60000);
renderLock();
